WITH scored AS (SELECT id, session_id, FIRST_VALUE(page, TRUE) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_page, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, LEAD(duration_sec, 2) OVER (ORDER BY duration_sec ASC, id ASC) AS next_duration_sec FROM web_events WHERE session_id IN (18, 24, 30)) SELECT session_id, MIN(next_duration_sec) AS min_next_duration_sec, APPROX_PERCENTILE(next_duration_sec, 0.5) AS next_duration_sec_p50, ROUND(AVG(cumulative_duration_sec), 2) AS avg_cumulative_duration_sec, COUNT(DISTINCT id) AS distinct_ids FROM scored GROUP BY session_id HAVING COUNT(DISTINCT id) > 1 ORDER BY min_next_duration_sec DESC NULLS FIRST;
